<script setup lang="ts">
import MaterialsPanel from '../materials/MaterialsPanel.vue'
import QuoteOcrPanel from './QuoteOcrPanel.vue'
import ArrivalPhotoPanel from '../materials/ArrivalPhotoPanel.vue'
import {candidateTotal,decimalProduct,type QuoteOcrDraft} from './quote-ocr'
import QuoteLines from '@/shared/ui/QuoteLines.vue'
import {quotePayload} from '@/shared/ui/presentation'
import RecordList from '@/shared/ui/RecordList.vue'
import {label} from '@/shared/ui/presentation'
import {computed,onMounted,ref,watch} from 'vue'
import {currentUser,httpClient} from '@/shared/http/client'
import {formalPayload,quotationApi,type QuoteCase} from './quotation'
const props=defineProps<{caseId:string;refreshToken?:number;recordsOnly?:boolean}>(),emit=defineEmits<{changed:[]}>(),api=quotationApi(httpClient,props.caseId)
const cs=computed(()=>currentUser.value?.roles.includes('CUSTOMER_SERVICE')),staff=computed(()=>cs.value||currentUser.value?.roles.includes('ADMIN')),shop=computed(()=>currentUser.value?.roles.includes('REPAIR_SHOP'))
const data=ref<QuoteCase>(),busy=ref(false),message=ref(''),draftLines=ref<QuoteOcrDraft[]>([{description:'',quantity:'',unitPrice:''}]),mode=ref<'FIXED_AMOUNT'|'PERCENTAGE'>('FIXED_AMOUNT'),markup=ref('0.00'),assessment=ref(''),historyType=ref(shop.value?'RAW':'EVENT'),historyPage=ref(1),historyTotal=ref(0),history=ref('')
const editable=computed(()=>!props.recordsOnly&&data.value&&(shop.value?['ARRIVED','WAITING_QUOTE','QUOTE_REVIEWING']:['ARRIVED','WAITING_QUOTE','QUOTE_REVIEWING','WAITING_INSURER_ASSESSMENT','WAITING_REPAIR_AUTHORIZATION']).includes(data.value.status))
const quoteStep=ref(false),photoStep=ref(false)
const showQuote=computed(()=>Boolean(data.value?.arrivalPhotoUploaded)&&!photoStep.value&&(quoteStep.value||Boolean(data.value?.rawQuote)))
const draftTotal=computed(()=>candidateTotal(draftLines.value))
const ocrPanel=ref<InstanceType<typeof QuoteOcrPanel>>(),quoteCommand=ref<{body:string;key:string}>()
async function load(){data.value=await api.get()}
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action()}catch(e){message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function post(path:string,body:unknown){data.value=await api.post(path,body);message.value='已保存；历史版本保留';emit('changed')}
async function submit(){if(!data.value||!editable.value)return;if(!data.value.arrivalPhotoUploaded)throw Error('请先上传到店照片');quotePayload(draftLines.value);const reviewed=await ocrPanel.value?.prepare(draftLines.value)??draftLines.value;const lines=quotePayload(reviewed).map((line,index)=>({...line,ocr:reviewed[index]?.ocr})),body={expectedVersion:data.value.version,assignmentVersion:data.value.assignmentVersion,lines},encoded=JSON.stringify(body);if(!quoteCommand.value||quoteCommand.value.body!==encoded)quoteCommand.value={body:encoded,key:crypto.randomUUID()};data.value=await api.post('raw-quotes',body,quoteCommand.value.key);draftLines.value=[{description:'',quantity:'',unitPrice:''}];message.value='已提交不可变报价新版本；OCR来源已保留';emit('changed')}
async function approve(){if(!data.value?.rawQuote)throw Error('需先有当前网点原始报价');await post('formal-quotes',formalPayload(data.value.version,data.value.rawQuote.id,mode.value,markup.value))}
async function recordAssessment(){if(!data.value)return;await post('assessments',{expectedVersion:data.value.version,amount:assessment.value})}
async function confirm(kind:'INSURER'|'CUSTOMER_SERVICE'){if(!data.value)return;await post(`confirmations/${kind}`,{expectedVersion:data.value.version})}
async function start(){if(!data.value)return;await post('start-repair',{expectedVersion:data.value.version,assignmentVersion:data.value.assignmentVersion})}
async function loadHistory(){const result=await api.history(historyType.value,historyPage.value);historyTotal.value=result.total;history.value=JSON.stringify(result.records,null,2)}
async function exportCsv(){if(!data.value?.formalQuote)return;const blob=await api.export(data.value.formalQuote.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`quote-v${data.value.formalQuote.version}.csv`;a.click();URL.revokeObjectURL(url)}
onMounted(()=>run(load));watch(()=>props.refreshToken,()=>run(load))
</script>
<template><section class="quotation"><p class="eyebrow">QUOTE / AUTHORIZATION</p><h2>{{ recordsOnly?'网点报价':shop?'网点报价':'报价、核损与维修授权' }}</h2><button :disabled="busy" @click="run(load)">刷新当前状态</button><p role="status">{{ message }}</p><template v-if="data"><p>状态 {{ label(data.status) }}；当前版本 {{ data.version }}</p><p v-if="!shop">币种 CNY，单位元；金额来自后端。正式对外行金额为准，展示单价保留6位。</p>
<details v-if="data.rawQuote" class="submitted-quote"><summary>已提交网点原始报价 v{{ data.rawQuote.version }} · {{ data.rawQuote.total }} 元</summary><QuoteLines :lines="data.rawQuote.lines"/></details><div v-if="shop&&editable"><ArrivalPhotoPanel :key="data.assignmentVersion" v-if="data.assignmentVersion!==undefined&&!showQuote" :case-id="caseId" :assignment-version="data.assignmentVersion" :uploaded="data.arrivalPhotoUploaded" @changed="run(load);emit('changed')" @next="quoteStep=true;photoStep=false"/><div v-if="quoteStep||Boolean(data.rawQuote)" v-show="showQuote"><button type="button" :disabled="busy" @click="photoStep=true">查看／补充到店照片</button><h3>提交原始报价新版本</h3><p>单价以元填写，最多2位小数；每次提交保留新版本。</p><QuoteOcrPanel v-if="data.assignmentVersion!==undefined" ref="ocrPanel" :key="data.assignmentVersion" :case-id="caseId" :assignment-version="data.assignmentVersion" :lines="draftLines" :locked="busy" @merge="draftLines=$event"/><section class="assessment-sheet" aria-label="定损清单核对表"><header><h3>定损 / 维修报价清单</h3><span>按原件行序核对 · 金额单位：元</span></header><div class="sheet-scroll" tabindex="0" aria-label="定损清单四列表格，可左右滑动"><table><caption class="sr-only">按原件行序显示配件/维修项目、数量、单价、金额</caption><thead><tr><th scope="col">配件/维修项目</th><th scope="col">数量</th><th scope="col">单价</th><th scope="col">金额</th></tr></thead><tbody><tr v-for="(line,index) in draftLines" :key="index"><td><textarea v-model="line.description" rows="2" maxlength="255" :aria-label="`第${index+1}项 配件/维修项目`" :disabled="busy"/><div class="row-tools"><span>第 {{ index+1 }} 行</span><button type="button" :aria-label="`删除第${index+1}项`" :disabled="busy||draftLines.length===1" @click="draftLines.splice(index,1)">删除</button><details v-if="line.ocr"><summary>原件依据</summary><p>候选 {{ line.ocr.itemIndex+1 }} · 请人工核对</p><label>单位<input v-model="line.unit" :disabled="busy"/></label><label>单据原行金额<input v-model="line.lineAmount" inputmode="decimal" :disabled="busy"/></label><p v-if="line.lineAmount&&decimalProduct(line.quantity,line.unitPrice)&&decimalProduct(line.quantity,line.unitPrice)!==decimalProduct('1',line.lineAmount)" role="alert">计算金额与单据原金额不一致，请核对。</p></details></div></td><td><input v-model="line.quantity" inputmode="numeric" :aria-label="`第${index+1}项 数量`" :disabled="busy"/></td><td><input v-model="line.unitPrice" inputmode="decimal" :aria-label="`第${index+1}项 单价（元）`" :disabled="busy"/></td><td class="line-amount">{{ decimalProduct(line.quantity,line.unitPrice)||'待补充' }}</td></tr></tbody><tfoot><tr><th scope="row" colspan="3">核对合计</th><td>{{ draftTotal||'待补充' }}</td></tr></tfoot></table></div><p class="table-hint">表内金额按数量 × 单价计算。原件金额只作核对依据，不自动累加跨页合计。</p></section><button type="button" :disabled="busy" @click="draftLines.push({description:'',quantity:'',unitPrice:''})">增加报价项</button><button :disabled="busy" @click="run(submit)">网点提交报价</button></div></div>
<div v-if="staff"><template v-if="data.formalQuote"><h3>正式报价 v{{ data.formalQuote.version }}（内部审核）</h3><p>原始合计 {{ data.formalQuote.originalTotal }}；加价 {{ data.formalQuote.markupAmount }}；对外总额 {{ data.formalQuote.total }} 元</p><QuoteLines :lines="data.formalQuote.lines" formal/><button :disabled="busy" @click="run(exportCsv)">导出仅对外价格的 CSV 数据</button></template><div v-if="cs&&editable"><h3>客服审核与总额加价</h3><select v-model="mode"><option value="FIXED_AMOUNT">固定金额（元）</option><option value="PERCENTAGE">比例（10.00代表10%）</option></select><input v-model="markup" inputmode="decimal" aria-label="加价值"><button :disabled="busy||!data.rawQuote" @click="run(approve)">审核并生成正式新版本</button><h3>最终核损金额</h3><input v-model="assessment" inputmode="decimal" placeholder="金额字符串，最多2位小数"><button :disabled="busy" @click="run(recordAssessment)">保存核损新版本</button><p>报价、核损金额或核损材料变化会清除两项确认并撤销旧授权。</p><button :disabled="busy||data.gate.insurerConfirmationRecorded" @click="run(()=>confirm('INSURER'))">代录保司确认</button><button :disabled="busy||data.gate.customerServiceConfirmationRecorded" @click="run(()=>confirm('CUSTOMER_SERVICE'))">客服确认当前依据</button></div><p v-if="data.assessment">最终核损 v{{ data.assessment.version }}：{{ data.assessment.amount }} 元</p></div>
<MaterialsPanel v-if="recordsOnly&&shop" records-only :filter-categories="['ARRIVAL_PHOTO','SHOP_QUOTE','ASSESSMENT']" :case-id="caseId" :status="data.status" :assignment-version="data.assignmentVersion"/><div v-if="!recordsOnly&&(!shop||Boolean(data.rawQuote))"><h3>开修条件</h3><ul class="gate-list"><li :class="{done:data.gate.finalAssessmentAmountRecorded}"><span>最终核损金额已录入</span><strong>{{ data.gate.finalAssessmentAmountRecorded?'已满足':'未满足' }}</strong></li><li :class="{done:data.gate.insurerConfirmationRecorded}"><span>保险公司已确认</span><strong>{{ data.gate.insurerConfirmationRecorded?'已满足':'未满足' }}</strong></li><li :class="{done:data.gate.customerServiceConfirmationRecorded}"><span>客服确认</span><strong>{{ data.gate.customerServiceConfirmationRecorded?'已满足':'未满足' }}</strong></li></ul><p>{{ data.authorized?'当前已授权，可以开始维修。':'条件未齐，请等待客服完成确认；系统会阻止未授权开修。' }}</p><button v-if="shop&&editable" :disabled="busy||!data.gate.allowed" @click="run(start)">开始维修（服务端复核）</button></div>
<details><summary>版本、确认及授权历史</summary><select v-model="historyType"><option value="RAW">原始报价</option><template v-if="staff"><option value="FORMAL">正式报价</option><option value="ASSESSMENT">核损</option><option value="CONFIRMATION">确认</option><option value="EVENT">授权/变更事件</option></template></select><input v-model.number="historyPage" type="number" min="1" aria-label="历史页码"><button :disabled="busy" @click="run(loadHistory)">查询历史</button><span>共 {{ historyTotal }} 条</span><RecordList :value="history"/></details></template></section></template>
<style scoped>
.assessment-sheet{margin:20px 0;border:1px solid var(--color-border);background:#fff;border-radius:8px;overflow:hidden}.assessment-sheet header{padding:18px 14px;text-align:center;border-bottom:1px solid var(--color-border)}.assessment-sheet header h3{margin:0 0 6px;font-size:18px}.assessment-sheet header span,.table-hint{font-size:12px;color:var(--color-text-secondary)}.table-hint{padding:0 12px;line-height:1.65}.sheet-scroll{max-width:100%;overflow:auto}.sheet-scroll:focus-visible{outline:2px solid var(--color-accent);outline-offset:-2px}.assessment-sheet table{width:100%;min-width:490px;border-collapse:collapse;table-layout:fixed;font-size:14px}.assessment-sheet th,.assessment-sheet td{border:1px solid var(--color-border);padding:8px;vertical-align:top}.assessment-sheet th{background:var(--color-surface-muted);font-weight:600;text-align:center}.assessment-sheet th:first-child{width:46%}.assessment-sheet th:nth-child(2){width:13%}.assessment-sheet th:nth-child(3){width:20%}.assessment-sheet th:nth-child(4){width:21%}.assessment-sheet td input,.assessment-sheet td textarea{width:100%;min-width:0;box-sizing:border-box;min-height:44px;margin:0;padding:8px 4px;border:1px solid transparent;border-radius:3px;background:transparent;color:var(--color-text);font:inherit}.assessment-sheet td textarea{min-height:60px;resize:vertical}.assessment-sheet td input{text-align:right}.assessment-sheet td input:focus,.assessment-sheet td textarea:focus{outline:2px solid var(--color-accent);background:#fff}.line-amount{text-align:right;padding-top:20px!important;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.assessment-sheet tfoot td{text-align:right;font-weight:650;font-variant-numeric:tabular-nums}.row-tools{display:flex;gap:6px;align-items:baseline;flex-wrap:wrap;font-size:11px;color:var(--color-text-secondary)}.row-tools button{min-height:32px;margin:0;padding:5px 8px;font-size:12px}.row-tools details{flex-basis:100%}.row-tools summary{cursor:pointer}.row-tools p{line-height:1.5}.row-tools label{font-size:12px}.submitted-quote{margin:16px 0}.submitted-quote summary{cursor:pointer;line-height:1.6}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.gate-list{padding:0!important;list-style:none}.gate-list li{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 0!important;border-bottom:1px solid var(--color-border)}.gate-list strong{color:var(--color-warning);font-size:12px}.gate-list li.done strong{color:var(--color-success)}textarea{width:100%;box-sizing:border-box}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
